# -*- coding: utf-8 -*-
"""Kịch bản review tiếng Việt (Phong cách Người Kể Chuyện - Storyteller), chia theo beat.
Tập 2: Ba năm làm vợ nội trợ bị chồng tặng hàng khuyến mãi, cô nộp đơn ly hôn trở thành nhà thiết kế trang sức tỷ đô được Tổng tài Hoắc thị sủng tận trời.
Nhân vật chính:
  - Lâm Uyển Vân (nữ chính - nhà thiết kế trang sức thiên tài)
  - Bùi Dật Phong (chồng cũ - tổng tài Bùi thị)
  - Bạch Hiểu Hiểu (trợ lý trà xanh của Bùi Dật Phong)
  - Hoắc Đình Uyên (nam chính - tổng tài tập đoàn Hoắc thị)
  - Lương Tĩnh Nghi (mẹ chồng cũ - mẹ Bùi Dật Phong)
  - Trình Công (trưởng phòng thiết kế trang sức Hoắc thị)
  - Phương Duyệt, Trần Vân (hai người bạn thân của Lâm Uyển Vân)
"""

TITLE = "CHỒNG TẶNG HÀNG KHUYẾN MÃI, VỢ LY HÔN TRỞ THÀNH NHÀ THIẾT KẾ TỶ ĐÔ"

BEATS = [
    # ---------------- HOOK ----------------
    ("0:00:00-0:00:42", "Suốt ba năm làm dâu hào môn không tiêu của nhà chồng một xu, đến ngày kỷ niệm, thứ mà Lâm Uyển Vân nhận được từ người chồng đầu ấp tay gối lại chỉ là một món hàng tặng kèm rẻ tiền, trong khi sợi dây chuyền chính hãng đắt giá đang nằm chễm chệ trên cổ cô trợ lý riêng của hắn."),
    ("0:09:45-0:10:35", "Không một lời ghen tuông cũng chẳng buồn rơi thêm một giọt nước mắt, cô thẳng tay khép chiếc hộp nhung lại, đặt tờ đơn ly hôn ra đi tay trắng lên bàn rồi lặng lẽ thu dọn hành lý rời khỏi căn biệt thự lạnh lẽo."),
    ("0:21:35-0:23:35", "Người chồng kiêu ngạo Bùi Dật Phong vẫn đinh ninh một người phụ nữ nội trợ rời khỏi hắn thì chẳng thể trụ nổi quá ba ngày, mà quên mất rằng trước khi lui về hậu phương, vợ mình từng là nhà thiết kế trang sức thiên tài được cả giới thượng lưu săn đón."),
    ("0:55:20-0:56:20,0:59:35-1:00:25", "Đến ngày cô đứng trên sân khấu tập đoàn Hoắc thị ra mắt bộ sưu tập sáu mươi tỷ tệ, cô trợ lý trà xanh còn cả gan ăn cắp bản thảo nháp mang tới vu khống cô đạo nhái, để rồi nhận lại một cú vả mặt kinh điển khiến cả nhà họ Bùi mất sạch thể diện."),
    ("1:14:05-1:14:48,4:14:40-4:15:25", "Và phía sau màn tái xuất rực rỡ ấy luôn có bóng dáng của Hoắc Đình Uyên, vị tổng tài quyền lực nhất Đế Kinh âm thầm làm chỗ dựa, sẵn sàng lật tung cả thành phố để bảo vệ cô trước mọi sóng gió."),
    ("0:00:43-0:01:25", "Bi kịch hôn nhân của Lâm Uyển Vân chạm tới giới hạn cuối cùng vào đúng buổi tối trước tiệc mừng sinh nhật của Bùi Dật Phong."),

    # ---------------- HỒI 1: BA NĂM NỘI TRỢ & SỢI DÂY CHUYỀN HÀNG TẶNG KÈM ----------------
    ("0:01:26-0:02:15", "Trong khi người làm từ nhà chính tìm tới thúc giục Uyển Vân phải qua chuẩn bị cỗ bàn từ sớm như mọi năm, thì Bùi Dật Phong lại đang ngồi giữa quán rượu sang trọng để mặc đám bạn bè tâng bốc cô trợ lý Bạch Hiểu Hiểu như nữ chủ nhân tương lai."),
    ("0:02:16-0:03:18", "Đám bạn công tử buông lời chê bai người vợ ở nhà đã cũ kỹ nhàm chán, còn Dật Phong chỉ cười khẩy cho rằng hôn nhân hào môn cần một người đàn bà biết nghe lời ở nhà quán xuyến, nên tờ đơn ly hôn mà Uyển Vân để lại chẳng qua chỉ là chiêu trò lạt mềm buộc chặt."),
    ("0:03:20-0:04:18", "Đêm đó trở về thấy vợ đã lên phòng nghỉ chứ không ngồi đợi ở ghế sofa như thường lệ, lại nghe quản gia báo tin cô từ chối tới nhà chính lo tiệc sinh nhật cho mình, Dật Phong vẫn ngạo mạn nghĩ rằng phụ nữ giận dỗi vài hôm rồi sẽ tự khắc ngoan ngoãn trở lại."),
    ("0:04:20-0:05:22", "Sáng hôm sau thức dậy không thấy bữa sáng bày sẵn trên bàn, Dật Phong tức tối ra lệnh cho trợ lý khóa sạch toàn bộ thẻ phụ của vợ để dạy cho cô một bài học, mà chẳng hề biết rằng suốt ba năm qua Uyển Vân chưa từng quẹt một đồng nào trong tấm thẻ ấy."),
    ("0:05:23-0:06:15", "Trong khi Bạch Hiểu Hiểu mang cháo tới tận văn phòng làm nũng lấy lòng, thì điện thoại của Dật Phong lại trống trơn, không còn những tin nhắn dặn dò lịch trình và báo cáo việc tiếp đón họ hàng chu đáo từ vợ như những năm trước."),
    ("0:06:16-0:06:56", "Đến giờ khai tiệc ở nhà chính, thấy con dâu vắng mặt còn Bạch Hiểu Hiểu lại xun xoe chạy tới giúp đỡ, bà mẹ chồng Lương Tĩnh Nghi lập tức nổi trận lôi đình, hết lời khen ngợi cô trợ lý hiểu chuyện và xúi giục con trai sớm bỏ người vợ không biết điều."),
    ("0:06:57-0:08:08", "Cùng lúc đó, Uyển Vân đang ngồi bên hai người bạn thân Phương Duyệt và Trần Vân. Nghe tin bạn mình cuối cùng cũng quyết định thoát khỏi gã chồng tệ bạc, hai cô bạn lập tức rút ra tấm thẻ hai mươi vạn tệ ép cô cầm lấy để mua sắm trang phục và gửi hồ sơ ứng tuyển vị trí nhà thiết kế trưởng của tập đoàn Hoắc thị."),
    ("0:08:09-0:09:03", "Đêm khuya trở về nhà trong hơi men, Dật Phong lớn tiếng trách móc vợ không coi gia đình ra gì. Uyển Vân chỉ bình thản buông một câu chúc mừng sinh nhật nhạt nhẽo, rồi nhắc cho hắn nhớ rằng tháng trước vào đúng ngày sinh nhật của cô, hắn thậm chí còn chẳng buồn bước chân về nhà."),
    ("0:09:04-0:09:50", "Sáng hôm sau, Bạch Hiểu Hiểu đích thân mang một hộp quà tới tận phòng khách, miệng nói là quà Dật Phong chọn riêng để dỗ dành vợ. Dật Phong đứng cạnh khoanh tay đầy vẻ bề trên, đinh ninh rằng khi mở hộp ra thấy trang sức đắt tiền, Uyển Vân sẽ cảm động mà rút lại ý định ly hôn."),
    ("0:09:51-0:10:45", "Thế nhưng vừa mở nắp hộp, ánh mắt Uyển Vân đã lạnh đi. Nằm trong hộp chỉ là sợi dây chuyền hàng tặng kèm, trong khi món trang sức chính hãng tinh xảo của bộ sưu tập ấy lại đang lấp lánh ngay trên cổ Bạch Hiểu Hiểu."),
    ("0:10:46-0:11:42", "Bị vạch trần tại trận, Dật Phong lúng túng nhận ra mình đã đưa nhầm hộp quà, còn Hiểu Hiểu vội vàng tháo dây chuyền ra giả vờ rơm rớm nước mắt nhận lỗi. Nhìn cô trợ lý làm bộ đáng thương, hắn lại mềm lòng bảo cô ta cứ giữ lấy mà đeo."),
    ("0:11:43-0:12:40", "Không dừng lại ở đó, Hiểu Hiểu còn chạy theo nắm tay Uyển Vân đòi chịu phạt, khiến Dật Phong quay sang quát mắng vợ nhỏ nhen. Uyển Vân lạnh lùng rụt tay lại, mỉa mai hai người bọn họ tự biên tự diễn quá giỏi rồi quay lưng đi thẳng ra trung tâm thương mại mua đồ chuẩn bị đi phỏng vấn."),
    ("0:12:41-0:14:12", "Trớ trêu thay, ngay tại cửa hàng thời trang, cô lại chạm mặt Dật Phong đang đi mua sắm cùng cô trợ lý. Gã chồng tự luyến lập tức ảo tưởng rằng vợ cố tình bám đuôi mình để mua quà lấy lòng, liền ngang ngược lao tới giật lấy túi đồ trên tay cô."),
    ("0:14:13-0:15:58", "Trong lúc giằng co, Dật Phong mạnh tay đẩy Uyển Vân ngã đập trán vào kệ trưng bày rớm máu. Nhìn những bộ trang phục công sở nữ rơi ra sàn chứ chẳng phải quà cáp tặng mình, hắn mới sững người bối rối, nhưng thứ nhận lại chỉ là ánh mắt lạnh băng cùng lời cảnh cáo của vợ rằng món nợ này cô nhất định sẽ trả lại gấp bội."),

    # ---------------- HỒI 2: TỜ ĐƠN RA ĐI TAY TRẮNG & MÀN TÁI XUẤT CỦA THIÊN TÀI ----------------
    ("0:16:00-0:17:20", "Tối hôm đó tại biệt thự, bà mẹ chồng Lương Tĩnh Nghi cùng Bạch Hiểu Hiểu kéo tới tận nơi hạch tội. Bà ta lớn tiếng tuyên bố đàn ông ra ngoài trăng hoa là chuyện bình thường, nếu Uyển Vân dám ly hôn thì phải cút khỏi nhà họ Bùi với hai bàn tay trắng."),
    ("0:17:21-0:18:45", "Uyển Vân chẳng nói chẳng rằng, lấy ra một xấp thẻ ngân hàng ném thẳng lên bàn. Hóa ra toàn bộ số tiền sinh hoạt phí mỗi tháng năm mươi vạn tệ mà nhà họ Bùi chuyển khoản để làm màu, cô chưa từng tiêu một đồng nào, dù Bạch Hiểu Hiểu đứng cạnh vẫn cố đơm đặt vu khống cô tiêu xài hoang phí."),
    ("0:18:46-0:20:14", "Đuổi mẹ và trợ lý về xong, Dật Phong lại giở giọng ban ơn, nói sẽ chuyển cho vợ một trăm vạn tệ với điều kiện cô phải đi mua quà xin lỗi Bạch Hiểu Hiểu vì đã làm cô trợ lý tổn thương."),
    ("0:20:15-0:21:15", "Ngay lúc đó, điện thoại của Dật Phong vang lên tiếng khóc lóc của Hiểu Hiểu báo tin vừa gặp tai nạn giao thông. Hắn lập tức cuống cuồng lao đi, trước khi bước ra khỏi cửa còn ra lệnh cho vợ phải ở nhà nấu cháo thanh đạm mang vào bệnh viện hầu hạ nhân tình."),
    ("0:21:16-0:22:32", "Tất nhiên Lâm Uyển Vân chẳng thèm bận tâm tới màn kịch vụng về ấy. Sáng hôm sau, cô có mặt tại trụ sở tập đoàn Hoắc thị để tham gia phỏng vấn. Đúng lúc phòng thiết kế đang hỗn loạn vì bản vẽ chủ đạo cho buổi họp báo bị mất, cô bình tĩnh bước tới chỉ ra ngay điểm yếu trong cấu trúc gắn đá của bản mẫu cũ."),
    ("0:22:33-0:23:55", "Dù đã ba năm không cầm bút vì chôn chân trong căn bếp nhà họ Bùi, chỉ mất chưa đầy hai mươi phút, Uyển Vân đã phác thảo xong một bản thiết kế hoàn hảo. Tổng tài Hoắc Đình Uyên vừa nhìn thấy nét vẽ đầy linh khí của cựu thiên tài bước ra từ trụ sở thiết kế quốc tế đã lập tức quyết định tuyển thẳng cô vào làm việc ngay ngày hôm sau."),
    ("0:24:00-0:25:14", "Tin vui trúng tuyển khiến hai người bạn thân Phương Duyệt và Trần Vân vỡ òa sung sướng. Ba chị em lập tức kéo nhau tới một quán ăn nhỏ mở tiệc ăn mừng sự trở lại của nhà thiết kế Lâm Uyển Vân."),
    ("0:25:15-0:26:48", "Nào ngờ giữa bữa tiệc, Bùi Dật Phong bất ngờ tìm tới tận nơi, mặt hầm hầm chất vấn tại sao cô dám tắt máy không mang cháo vào bệnh viện cho Hiểu Hiểu. Nghe vợ thản nhiên báo tin vừa đi phỏng vấn xin việc, hắn lại cười khẩy bảo cô chỉ cần ngoan ngoãn ở nhà nhẫn nhịn như ba năm qua là đủ."),

    # ---------------- HỒI 3: TRẢ LẠI BÁU VẬT GIA TRUYỀN, CHÍNH THỨC RỜI KHỎI NHÀ HỌ BÙI ----------------
    ("0:26:50-0:28:15", "Bị Dật Phong ép tới tận phòng bệnh để xin lỗi nhân tình, Uyển Vân chỉ liếc mắt đã nhìn thấu cái chân quấn băng trắng xóa nhưng vẫn cử động thoăn thoắt của Bạch Hiểu Hiểu. Trước lời thúc giục đòi quà xin lỗi từ chồng, cô khẽ mỉm cười bảo mình có chuẩn bị một món quà vô cùng xứng đáng."),
    ("0:28:16-0:29:25", "Ngay trước mặt hai người, Uyển Vân đưa tay tháo sợi dây chuyền ngọc lục bảo gia truyền của nhà họ Bùi, thứ chỉ dành riêng cho con dâu trưởng, rồi ném thẳng vào lòng Bạch Hiểu Hiểu như trao lại ngôi vị bà chủ nhà họ Bùi mà cô chẳng còn chút thiết tha."),
    ("0:29:26-0:30:45", "Trở về biệt thự trong đêm, Uyển Vân thu dọn vài bộ quần áo tự mua bằng tiền của mình, gửi lại chìa khóa và tờ đơn ly hôn đã ký sẵn cho bác quản gia già rồi kéo vali bước ra khỏi cánh cổng nhà họ Bùi, chính thức bắt đầu cuộc đời tự do."),
    ("0:30:50-0:32:40", "Ngày đầu tiên nhận việc tại tập đoàn Hoắc thị, trưởng phòng Trình Công đã xếp cho cô chỗ ngồi đẹp nhất nhìn ra toàn cảnh thành phố. Buổi chiều cùng ngày, vì trưởng phòng bận việc đột xuất, Uyển Vân được cử đi tháp tùng tổng tài Hoắc Đình Uyên tham dự buổi triển lãm trang sức lớn trong ngành."),
    ("0:32:45-0:34:00", "Tại buổi triển lãm, khi thấy cô nhân viên mới có chút hồi hộp khi ngồi hàng ghế đầu, Hoắc Đình Uyên nhẹ nhàng trấn an cô. Chỉ qua vài bức ảnh trưng bày trên màn hình lớn, Uyển Vân đã tinh tường nhận ra phong cách chế tác của bậc tiền bối Đỗ Vũ Vi."),
    ("0:34:05-0:36:40", "Khi được mời đặt câu hỏi giao lưu, những phân tích sắc sảo của Uyển Vân về kỹ thuật đảo ngược cấu trúc đá phụ đã khiến cả hội trường lẫn nhà thiết kế Đỗ Vũ Vi phải trầm trồ thán phục, càng làm Hoắc Đình Uyên thêm trân trọng tài năng bị vùi lấp suốt ba năm của cô."),
    ("0:36:45-0:38:20", "Đúng lúc ấy, Bùi Dật Phong nhận được tin báo vợ mình bỏ nhà đi lại đang ngồi cạnh tổng tài họ Hoắc liền hùng hổ xông tới nắm chặt cổ tay cô định lôi về. Nhưng Hoắc Đình Uyên đã lập tức đứng chắn trước mặt cô, lạnh lùng tuyên bố Lâm Uyển Vân hiện là người của tập đoàn Hoắc thị, không ai được phép cưỡng ép."),
    ("0:38:22-0:39:25", "Trở về công ty, Uyển Vân áy náy định nộp đơn xin nghỉ vì sợ chuyện cá nhân làm ảnh hưởng tới uy tín tập đoàn. Thế nhưng Hoắc Đình Uyên thẳng thừng gạt đi, khẳng định người mất mặt là kẻ tới gây rối chứ không phải một nhân tài mà anh đã đích thân chọn lựa."),
    ("0:39:27-0:41:10", "Tối muộn bước ra khỏi tòa nhà Hoắc thị, Dật Phong lại đứng chặn ở cửa, ra lệnh cho cô phải nghỉ việc về bộ phận thiết kế của Bùi thị làm dưới trướng hắn. Uyển Vân dứt khoát từ chối, chỉ để lại lời nhắn rằng khi nào hắn chịu ký vào đơn ly hôn thì hãy mở miệng nói chuyện."),

    # ---------------- HỒI 4: CÚ VẢ MẶT SÁU MƯƠI TỶ TẠI BUỔI HỌP BÁO HOẮC THỊ ----------------
    ("0:41:15-0:43:28", "Không kéo được vợ về, Dật Phong lại nghe lời mè nheo của Bạch Hiểu Hiểu mà đón cô trợ lý về ngủ tại biệt thự. Nửa đêm, Hiểu Hiểu lén lấy điện thoại gửi ảnh khiêu khích cho chính thất, nào ngờ Uyển Vân chỉ thản nhiên nhắn lại một câu cảm ơn vì đã cung cấp thêm bằng chứng ngoại tình cho tòa án."),
    ("0:43:30-0:45:10", "Ở công ty, Hoắc Đình Uyên đã thức trắng đêm tự tay tinh chỉnh lại từng chi tiết nhỏ trên bản mẫu của Uyển Vân để kịp đưa vào sản xuất, đồng thời phá lệ ra lệnh ghi tên cô làm nhà thiết kế chính của toàn bộ dòng sản phẩm mới dù cô mới vào làm được hai ngày."),
    ("0:45:12-0:47:00", "Buổi tối khi cả phòng thiết kế đang chuẩn bị đi ăn liên hoan chào đón thành viên mới, Dật Phong lại tìm tới gây sự vì bị vợ chặn số và nghe lời Hiểu Hiểu vu oan rằng cô gọi điện mắng chửi. Trước mặt toàn bộ đồng nghiệp mới, Uyển Vân thẳng thừng giới thiệu hắn chỉ là người chồng cũ đang làm thủ tục ly hôn."),
    ("0:47:05-0:49:10", "Ngày hôm sau, Dật Phong còn ngông cuồng xông thẳng lên văn phòng tầng cao nhất của Hoắc Đình Uyên đòi người, nhưng bị vị tổng tài họ Hoắc dùng khí thế áp đảo đuổi thẳng ra ngoài, khẳng định Lâm Uyển Vân là một cá thể độc lập chứ không phải vật sở hữu của nhà họ Bùi."),
    ("0:49:12-0:51:35", "Tối đó, bà mẹ chồng Lương Tĩnh Nghi ép Uyển Vân về nhà chính để dạy dỗ, có cả Bạch Hiểu Hiểu ngồi sẵn chờ xem kịch hay. Khi bà ta lớn tiếng mắng cô ăn bám năm mươi vạn mỗi tháng, Uyển Vân thẳng mặt vạch trần chuyện cô đã hoàn trả từng đồng và chính Hiểu Hiểu mới là kẻ biết rõ nhất, rồi hiên ngang bước ra khỏi cửa."),
    ("0:51:36-0:53:38", "Thấy Uyển Vân ngày càng cứng rắn và độc lập tài chính, Bạch Hiểu Hiểu sợ mất chỗ dựa liền rỉ tai xúi giục Dật Phong phải hủy hoại sự nghiệp của vợ tại buổi họp báo sắp tới, để cô không còn chốn dung thân trong ngành thiết kế mà buộc phải quay về cầu xin hắn."),
    ("0:53:40-0:55:22", "Ngày diễn ra buổi họp báo ra mắt trang sức mới của tập đoàn Hoắc thị, giữa hàng trăm khách mời thượng lưu và giới truyền thông, tổng tài Hoắc Đình Uyên trang trọng bước lên sân khấu, đích thân xướng tên nhà thiết kế chính Lâm Uyển Vân."),
    ("0:55:23-0:56:35", "Ngay khoảnh khắc Uyển Vân chuẩn bị bước lên bục vinh quang, Bạch Hiểu Hiểu bất ngờ lao ra giữa hội trường, giơ cao một tập bản vẽ rồi lớn tiếng tố cáo toàn bộ tác phẩm hôm nay của Lâm Uyển Vân đều là hàng đạo nhái từ thiết kế mà cô ta vẽ riêng cho tổng tài Bùi thị."),
    ("0:56:36-0:58:05", "Cả hội trường lập tức xôn xao bàn tán. Đáng hổ thẹn hơn, Bùi Dật Phong cũng bước ra phụ họa, nhận vơ rằng tập bản thảo nháp mà hắn lấy trộm trong phòng làm việc ở nhà là tác phẩm của Hiểu Hiểu, rồi giả nhân giả nghĩa cúi đầu xin lỗi thay cho người vợ nội trợ ham hư vinh."),
    ("0:58:06-0:59:32", "Thế nhưng khi hai kẻ kia đang đắc ý tưởng đã dìm được Uyển Vân xuống bùn đen, Hoắc Đình Uyên bình thản cầm micro bước lên. Anh dõng dạc tuyên bố bản vẽ gốc của bộ sưu tập này được Lâm Uyển Vân phác thảo trực tiếp ngay trước mặt anh và toàn bộ phòng thiết kế Hoắc thị chỉ trong vòng hai mươi phút ngày phỏng vấn."),
    ("0:59:33-1:00:55", "Bước lên sân khấu với phong thái tự tin rạng ngời, Uyển Vân giải thích rõ tờ giấy trong tay Hiểu Hiểu chỉ là bản nháp cô đã vứt bỏ ở nhà, còn thành phẩm hoàn mỹ hôm nay chính là bản nâng cấp do cô và đích thân tổng tài Hoắc Đình Uyên cùng hoàn thiện, định giá ba triệu tệ mỗi bộ với số lượng giới hạn hai nghìn bộ."),
    ("1:00:56-1:02:30", "Thấy các phu nhân danh gia vọng tộc tranh nhau đặt mua sạch sẽ, Bạch Hiểu Hiểu mất khôn gào lên chửi bới cả giới thượng lưu là lũ đạo đức giả phí tiền mua đá vụn. Quá mất mặt trước toàn bộ giới hào môn Đế Kinh, Bùi Dật Phong tái mặt vung tay tát thẳng vào mặt nhân tình ngay giữa sóng truyền thông."),
    ("1:02:50-1:04:45", "Sau buổi họp báo thảm họa, gia đình họ Bùi trở thành trò cười cho cả giới kinh doanh. Trở về nhà chính, cả Dật Phong lẫn bà Lương Tĩnh Nghi đều tức giận trách mắng Hiểu Hiểu ngu xuẩn làm đứt gãy toàn bộ mạch quan hệ làm ăn của tập đoàn."),
    ("1:04:46-1:06:20", "Thấy nguy cơ bị đá ra khỏi cửa, Bạch Hiểu Hiểu liền vớ lấy con dao gọt hoa quả kề lên cổ diễn màn tự tử, vừa khóc lóc vừa tự nhận mình chỉ vì quá yêu Dật Phong nên mới làm liều, khiến gã đàn ông nhu nhược lại một lần nữa mủi lòng tha thứ."),
    ("1:06:25-1:09:05", "Trái ngược với cảnh gà bay chó sủa ở nhà họ Bùi, buổi tiệc mừng công tại tập đoàn Hoắc thị tràn ngập tiếng cười. Bộ sưu tập trang sức cháy hàng chỉ trong một ngày, mang về doanh thu sáu mươi tỷ tệ, giúp Uyển Vân nhận ngay tấm séc tiền thưởng nóng năm triệu tệ cùng khoản hoa hồng hai mươi triệu tệ sắp về tài khoản."),
    ("1:09:10-1:11:05", "Có tiền thưởng trong tay, việc đầu tiên Uyển Vân làm là hẹn gặp hai cô bạn thân để trả lại hai mươi vạn tiền vay lúc khó khăn, đồng thời gửi gắm bốn trăm năm mươi vạn tệ nhờ bạn giữ hộ làm quỹ dự phòng cho cuộc chiến ly hôn sắp tới."),

    # ---------------- HỒI 5: MỨC LƯƠNG HAI MƯƠI VẠN SỈ NHỤC & MÀN GIẢI CỨU CỦA HOẮC ĐÌNH UYÊN ----------------
    ("1:11:10-1:12:25", "Chỉ trong một ngày, tập đoàn Bùi thị bốc hơi hơn ba mươi tỷ giá trị vốn hóa vì bê bối tại buổi họp báo. Nghe lời xúi bẩy của Bạch Hiểu Hiểu, Dật Phong liền giả vờ đồng ý ký đơn ly hôn để lừa Uyển Vân tới gặp mặt riêng."),
    ("1:12:26-1:13:35", "Khi Uyển Vân tới nơi, hắn không những chẳng chịu ký đơn mà còn vênh váo đề nghị cho cô về Bùi thị làm việc với mức lương bố thí hai mươi vạn tệ một năm. Uyển Vân bật cười khinh bỉ, thẳng thừng tuyên bố riêng tiền thưởng và hoa hồng một dự án của cô ở Hoắc thị đã lên tới hai mươi lăm triệu tệ, cô không có nghĩa vụ đi xóa đói giảm nghèo cho công ty của hắn."),
    ("1:13:36-1:14:58", "Bị chạm tự ái, Dật Phong nổi điên khóa cửa định dùng vũ lực cưỡng bức vợ ngay tại phòng nghỉ để trói buộc cô. Đúng giây phút nguy cấp nhất, cánh cửa bị đạp tung, Hoắc Đình Uyên xuất hiện kịp thời tung cú đấm trời giáng hạ gục Dật Phong, rồi cởi áo vest khoác lên bờ vai run rẩy của Uyển Vân đưa cô về nhà."),
    ("1:15:05-1:16:35", "Không thể dung thứ thêm một giây nào nữa, ngay sáng hôm sau Uyển Vân tìm gặp luật sư Trương Bằng để lập hồ sơ khởi kiện ly hôn đơn phương, đồng thời mang chiếc áo vest đã giặt sạch lên cảm ơn sự cứu giúp của Hoắc Đình Uyên."),
    ("1:16:40-1:18:40", "Dưới sự dẫn dắt của Uyển Vân, cả phòng thiết kế Hoắc thị hăng hái tăng ca sáng tạo năm mẫu thiết kế mở rộng. Tối muộn hôm đó, chính Hoắc Đình Uyên còn chu đáo đặt đồ ăn đêm gửi tới tận phòng làm việc để tiếp sức cho cô và các đồng nghiệp."),
    ("1:18:45-1:20:35", "Nào ngờ vừa bước về tới cửa khu nhà thuê, bà mẹ chồng Lương Tĩnh Nghi đã đứng phục sẵn. Bà ta trơ trẽn ra lệnh cho Uyển Vân phải nghỉ việc ở Hoắc thị và giao nộp toàn bộ bản quyền thiết kế sáu mươi tỷ về cho nhà họ Bùi làm không công. Uyển Vân bình tĩnh bật điện thoại ghi âm toàn bộ những lời lẽ ngang ngược ấy rồi đóng sập cửa lại."),
    ("1:20:36-1:22:30", "Sau khi gửi đoạn ghi âm cho luật sư lưu vào hồ sơ khởi kiện, hôm sau Uyển Vân trình lên Hoắc Đình Uyên ba bản thiết kế dự phòng mới chỉ trong một đêm, khiến vị tổng tài vốn khắt khe cũng phải gật đầu tán thưởng và chọn ngay bốn mẫu của cô vào bộ sưu tập kế tiếp."),
    ("1:22:35-1:25:20", "Chưa dừng lại ở đó, Bạch Hiểu Hiểu còn chủ động chặn đường Uyển Vân ở hành lang, cố tình canh đúng góc khuất của camera để tự ngã trầy đầu gối rồi khóc lóc vu oan rằng chính thất hành hung mình."),
    ("1:25:25-1:26:50", "Tin lời nhân tình, Bùi Dật Phong lập tức dùng quyền hạn người chồng trên giấy tờ kết hôn để yêu cầu ngân hàng đóng băng toàn bộ tài khoản đứng tên Lâm Uyển Vân, đinh ninh rằng khi không còn một xu dính túi, cô sẽ phải cúi đầu quay về van xin hắn."),
    ("1:26:54-1:28:35", "Khi Uyển Vân tới ngân hàng làm thủ tục mở khóa, Dật Phong và Hiểu Hiểu cố tình xuất hiện trước mặt cô để nhận ba thỏi vàng ròng mới đặt đúc. Thế nhưng trái với vẻ ghen tuông mà hắn mong đợi, Uyển Vân chỉ bình thản giơ điện thoại chụp lại cảnh hai người ôm ấp làm bằng chứng ngoại tình trước tòa."),
    ("1:28:40-1:30:45", "Biết chuyện Uyển Vân bị chồng cũ chơi xấu phong tỏa tài khoản cá nhân, trưởng phòng Trình Công lập tức báo cáo cấp trên và làm riêng cho cô một tấm thẻ ngân hàng vô danh của tập đoàn, chuyển trọn vẹn hai mươi triệu tệ tiền hoa hồng vào đó để Dật Phong không bao giờ có thể chạm tới."),
    ("1:30:50-1:33:20", "Cầm tấm thẻ hai mươi triệu tệ trong tay, Uyển Vân lập tức mang tới giao cho cô bạn thân cất giữ và ký thỏa thuận ủy thác đầu tư rõ ràng. Ngay tối hôm đó, cô khoác lên mình bộ dạ hội lộng lẫy do chính Hoắc Đình Uyên chuẩn bị để cùng anh bước vào buổi đấu giá trang sức thượng lưu."),

    # ---------------- HỒI 6: ĐÊM ĐẤU GIÁ THƯỢNG LƯU & BUỔI HỌP BÁO LẬT NGƯỢC THẾ CỜ ----------------
    ("1:33:25-1:35:50", "Tại sảnh đấu giá, sự xuất hiện của tổng tài Hoắc Đình Uyên bên cạnh nữ thiết kế xinh đẹp khiến cả hội trường ngoái nhìn. Bùi Dật Phong đi cùng Bạch Hiểu Hiểu thấy vợ mình ăn vận lộng lẫy liền nổi cơn ghen, lao tới đòi kéo cô về nhưng bị Hoắc Đình Uyên thẳng thừng chặn lại."),
    ("1:35:51-1:37:25", "Đinh ninh rằng mọi thẻ ngân hàng của Uyển Vân đều đã bị khóa sạch, Bạch Hiểu Hiểu lén chạy ra báo với ban tổ chức rằng cô không đủ tư cách tài chính để vào cửa. Nào ngờ khi nhân viên tới kiểm tra, Hoắc Đình Uyên chỉ lạnh nhạt tuyên bố cô là người đồng hành của anh, khiến nhân viên vội vã cúi đầu xin lỗi."),
    ("1:37:26-1:38:55", "Không bỏ qua dễ dàng, Uyển Vân yêu cầu ban tổ chức chỉ mặt kẻ vừa báo cáo nặc danh. Khi Bạch Hiểu Hiểu bị vạch mặt ngay giữa sảnh tiệc, cả cô ả lẫn Bùi Dật Phong đều bị bảo vệ mời thẳng ra khỏi hội trường trong tiếng xì xào khinh bỉ của giới thượng lưu."),
    ("1:39:00-1:41:55", "Trong buổi đấu giá, Hoắc Đình Uyên chi bộn tiền mua lại hai bộ trang sức kỷ vật năm xưa của cha mẹ mình. Khi anh đưa Uyển Vân về qua cổng tập đoàn cũng là lúc mẹ ruột anh mang canh bổ tới thăm con trai; vừa thấy lần đầu tiên trên xe của cậu con trai lạnh lùng có một cô gái, phu nhân nhà họ Hoắc đã mừng rỡ nắm chặt tay Uyển Vân hỏi thăm đủ điều."),
    ("1:42:00-1:45:05", "Khác hẳn với sự cay nghiệt của mẹ chồng nhà họ Bùi, mẹ của Hoắc Đình Uyên vô cùng tâm lý và cởi mở, hết lời khen ngợi cô thiết kế trẻ tài giỏi và hẹn ngày mời cô về nhà ăn cơm, khiến trái tim vốn đã nguội lạnh vì hôn nhân của Uyển Vân bỗng dâng lên một nỗi ấm áp lạ thường."),
    ("1:45:10-1:48:15", "Ở công ty, không chỉ bốn bản thiết kế của Uyển Vân được chọn làm chủ đạo mà một đồng nghiệp trẻ do cô tận tình chỉ dẫn cũng giành được suất sản xuất và nhận thưởng năm vạn tệ, giúp toàn bộ phòng thiết kế càng thêm đoàn kết và nể phục cô."),
    ("1:48:20-1:52:55", "Mấy ngày sau, khi nhận được thư triệu tập ly hôn từ luật sư, Bùi Dật Phong điên cuồng tìm tới tận căn hộ thuê của Uyển Vân, xé nát bức thư ngay trước mặt cô rồi tuyên bố đã tự ý đánh thêm chìa khóa để dọn tới ăn dầm nằm dề tại đây."),
    ("1:53:00-1:56:10", "Không thèm đôi co với kẻ ngang ngược, Uyển Vân lập tức dùng kế gậy ông đập lưng ông, nhắn tin báo địa chỉ cho Bạch Hiểu Hiểu. Chỉ vài phút sau, cô trợ lý đã gọi điện khóc lóc dọa dẫm kéo Dật Phong đi mất, còn Uyển Vân ngay trong đêm liền thu dọn hành lý chuyển khỏi căn nhà thuê thiếu an toàn."),
    ("1:56:15-1:58:35", "Biết chuyện cô đang phải tìm chỗ ở mới để tránh sự quấy rối của chồng cũ, Hoắc Đình Uyên lập tức đưa cô tới một khu căn hộ cao cấp có hệ thống an ninh nghiêm ngặt bậc nhất thành phố. Anh lấy lý do nhờ cô trông coi giúp căn nhà để trống và chỉ thu mức giá tượng trưng bốn nghìn tệ mỗi tháng."),
    ("1:58:38-2:02:55", "Bắt gặp Uyển Vân bước xuống từ xe của Hoắc Đình Uyên, Dật Phong lại giở giọng ghen tuông mắng cô ngoại tình, còn Bạch Hiểu Hiểu đứng sau lưng âm thầm tung ảnh cắt ghép lên mạng xã hội tạo cơn bão dư luận nhằm ép Dật Phong phải dứt khoát bỏ vợ để mình lên thay."),
    ("2:03:00-2:05:15", "Cổ phiếu Bùi thị sụt giảm nghiêm trọng khiến bà Lương Tĩnh Nghi phải hạ mình tìm gặp Uyển Vân, yêu cầu cô xuất hiện tại buổi họp báo truyền hình trực tiếp để nói dối rằng hai vợ chồng vẫn mặn nồng và những bức ảnh kia chỉ là trò chơi trong bữa tiệc."),
    ("2:05:16-2:06:58", "Uyển Vân giả vờ gật đầu đồng ý. Thế nhưng ngay khi Bùi Dật Phong vừa đọc xong bài diễn văn tẩy trắng trước hàng chục ống kính máy quay trực tiếp toàn quốc, cô đã cầm micro đứng dậy, dõng dạc công bố toàn bộ sự thật rằng hai người đang làm thủ tục ly hôn vì hắn ngoại tình với thư ký, đóng băng tài khoản của vợ và ép cô tới đây diễn kịch."),
    ("2:07:00-2:09:20", "Cú lật kèo ngay trên sóng trực tiếp khiến Dật Phong chết đứng. Bạch Hiểu Hiểu cuống quýt giả vờ ngất xỉu để giải vây nhưng lại ngây ngô khoe khoang màn diễn kịch của mình ngay khi vừa vào phòng nghỉ, khiến Dật Phong nhận ra bấy lâu nay mình bị cô ả dắt mũi từ chuyện dây chuyền đến chuyện mua từ khóa tìm kiếm, liền tức giận tát cô ả lần thứ hai."),
    ("2:09:22-2:12:05", "Tối hôm đó, Uyển Vân vui vẻ mở tiệc hải sản chiêu đãi cả phòng thiết kế cùng tổng tài Hoắc Đình Uyên. Trước sự dũng cảm dám vạch trần sự giả dối ngay trên sóng truyền thông của cô, đồng nghiệp ai nấy đều nể phục, còn ánh mắt Hoắc Đình Uyên nhìn cô lại càng thêm phần dịu dàng."),
    ("2:12:08-2:16:40", "Hôm sau, khi Dật Phong tới cổng tập đoàn Hoắc thị làm loạn đòi gặp vợ thì bị bảo vệ tống cổ. Để giúp Uyển Vân chấm dứt triệt để sự dây dưa này, Hoắc Đình Uyên đã đề nghị cô làm người đồng hành cùng anh đi gặp đối tác trong chuyến công tác sắp tới, đổi lại anh sẽ cử đội ngũ pháp vụ bất khả chiến bại của Hoắc thị đứng ra giải quyết vụ án ly hôn cho cô."),

    # ---------------- HỒI 7: VỤ BẮT CÓC TRONG KỲ NGHỈ LẠNH & NĂM MƯƠI TRIỆU TIỀN BỒI THƯỜNG ----------------
    ("2:16:50-2:20:45", "Trong buổi tiệc rượu thương mại tại Hàng Thành, Uyển Vân xuất hiện lộng lẫy bên cạnh Hoắc Đình Uyên. Dật Phong cũng có mặt tại đó, vừa thấy vợ liền lao tới định lôi đi nhưng bị Đình Uyên bẻ quặt cổ tay cảnh cáo, sau đó anh còn ân cần rút khăn tay lau vết trang điểm bị nhòe cho cô."),
    ("2:20:50-2:24:35", "Chán ngán những rắc rối do Bạch Hiểu Hiểu gây ra, Dật Phong ra lệnh điều chuyển cô ả về chi nhánh Dung Thành và cấm quay lại Đế Kinh. Không cam lòng mất đi mỏ vàng, đêm chia tay Hiểu Hiểu đã lén bỏ thuốc vào rượu của Dật Phong để tạo hiện trường giả trên giường khách sạn rồi chụp ảnh gửi thẳng cho Uyển Vân."),
    ("2:24:40-2:28:40", "Sáng hôm sau tại sảnh khách sạn, khi Dật Phong chạm mặt Uyển Vân đi công tác về cùng Hoắc Đình Uyên, cô chỉ cười nhạt giơ những bức ảnh nóng bỏng mà nhân tình của hắn vừa gửi tới, đồng thời không quên mua riêng một hộp bánh đặc sản tặng cho vị tổng tài đã luôn chu đáo bảo vệ mình."),
    ("2:28:45-2:33:10", "Ngày nhận được giấy triệu tập của tòa án cùng tập hồ sơ bằng chứng ngoại tình dày cộp từ luật sư Trương Bằng, Bùi Dật Phong hoàn toàn mất hết lý trí, gào lên rằng trừ khi hắn chết chứ không bao giờ cho phép Lâm Uyển Vân bước ra khỏi cuộc hôn nhân này."),
    ("2:33:12-2:34:38", "Sáng hôm sau, ngay tại cổng tập đoàn Hoắc thị, Dật Phong liều lĩnh lao tới khống chế Uyển Vân đẩy lên xe, tịch thu điện thoại rồi đưa cô về giam lỏng trong biệt thự nhà họ Bùi với ý định nhốt cô đủ ba mươi ngày để cô bị công ty sa thải vì tự ý bỏ việc."),
    ("2:34:40-2:37:10", "Thế nhưng hắn đã tính sai một bước lớn. Thấy Uyển Vân đến giờ làm việc mà không xuất hiện, điện thoại lại bị ngắt máy bất thường, trưởng phòng Trình Công lập tức báo cho Hoắc Đình Uyên. Chỉ mất vài phút trích xuất camera an ninh, vị tổng tài họ Hoắc đã lập tức báo cảnh sát và đích thân dẫn người thẳng tiến tới biệt thự nhà họ Bùi."),
    ("2:37:45-2:40:38", "Trong căn phòng bị khóa trái, Bạch Hiểu Hiểu còn mò tới giả vờ quỳ lạy xin tha thứ rồi cố tình xô đẩy làm Uyển Vân ngã đập đầu vào cạnh bàn, hòng diễn màn kịch nạn nhân trước mặt Dật Phong."),
    ("2:40:40-2:43:30", "Đúng lúc Dật Phong đang định cho người lén chuyển Uyển Vân đi nơi khác để trốn tránh cảnh sát, cô đã nhanh trí đập vỡ cửa sổ tầng hai hô hoán cầu cứu. Trước bằng chứng rành rành, cảnh sát cùng Hoắc Đình Uyên lập tức ập vào giải cứu cô và còng tay áp giải Bùi Dật Phong về đồn vì tội bắt giữ người trái pháp luật."),
    ("2:43:35-2:46:15", "Có đội ngũ pháp vụ hùng hậu của Hoắc thị đứng ra hoàn thiện hồ sơ hình sự, Bùi Dật Phong đứng trước nguy cơ thân bại danh liệt. Luật sư của hắn vội vã tìm gặp Uyển Vân, đề nghị mở khóa toàn bộ thẻ ngân hàng và bồi thường năm mươi triệu tệ tiền mặt để đổi lấy giấy bãi nại."),
    ("2:46:20-2:50:30", "Để cảm ơn sự giúp đỡ tận tình của Hoắc Đình Uyên, Uyển Vân đã tự tay nấu một bữa cơm gia đình mời anh tới căn hộ thưởng thức và tặng anh một chiếc cà vạt thanh lịch. Lúc tiễn anh ra cửa, cô mới bất ngờ phát hiện hóa ra căn hộ đối diện ngay trước cửa nhà mình chính là nơi ở của vị tổng tài họ Hoắc."),
    ("2:50:35-2:55:10", "Sáng hôm sau, sau khi năm mươi triệu tệ tiền bồi thường đã nằm gọn trong tài khoản, Uyển Vân tới Cục Dân Chính làm thủ tục ly hôn. Bà mẹ chồng Lương Tĩnh Nghi còn kéo tới trước cổng ăn vạ, vu khống cô tham tiền và định giơ tay tát cô, nhưng Uyển Vân chỉ nhẹ nhàng nghiêng người né tránh khiến bà ta tự ngã sóng xoài trước sự chê cười của đám đông khi biết cô là nhà thiết kế sáu mươi tỷ của Hoắc thị."),
    ("2:55:12-2:59:00", "Dưới sức ép của bản án hình sự treo lơ lửng trên đầu, Dật Phong buộc phải ký vào đơn đăng ký ly hôn và nhận giấy hẹn ba mươi ngày chờ đợi. Vừa bước ra khỏi Cục Dân Chính, Hoắc Đình Uyên đã đứng đợi sẵn với một bó hoa tươi thắm chúc mừng cô thoát khỏi bể khổ, đồng thời thẳng tay chặn đứng cơn ghen vô lý của Dật Phong."),

    # ---------------- HỒI 8: ÂM MƯU BỎ THUỐC HÈN HẠ, THƯƠNG HIỆU CHI LAN & LỜI TỎ TÌNH ----------------
    ("2:59:05-3:03:58", "Sau buổi đi siêu thị mua đồ nấu cơm tối cùng nhau, Hoắc Đình Uyên hào phóng chuyển ngay mười vạn tệ tiền ăn để mỗi ngày được thưởng thức hộp cơm trưa do chính tay Uyển Vân chuẩn bị, rồi hai người còn ăn ý phối hợp diễn một vở kịch nhỏ lừa Bùi Dật Phong rút lui khỏi khu đất vàng tổ chức buổi họp báo tiếp theo."),
    ("3:04:02-3:06:45", "Không cam tâm mất vợ, nghe lời xúi giục của Bạch Hiểu Hiểu, đêm trước ngày họp báo đợt hai, Dật Phong lấy cớ dọa hủy đơn đăng ký ly hôn trong thời gian chờ để ép Uyển Vân quay lại biệt thự lấy nốt đồ đạc và ăn bữa cơm chia tay cuối cùng. Lo lắng cho sự an toàn của cô, Hoắc Đình Uyên đã đích thân lái xe đi cùng và hẹn đúng ba mươi phút nếu cô chưa ra sẽ lập tức xông vào."),
    ("3:06:50-3:09:45", "Quả nhiên trong ly rượu chia tay, Dật Phong đã lén bỏ thuốc mê liều mạnh hòng chiếm đoạt cô để hủy bỏ việc ly hôn. Thế nhưng đúng hẹn ba mươi phút, Hoắc Đình Uyên đã phá cửa xông vào, bế thốc Uyển Vân đang dần mất đi ý thức ra xe và gọi bác sĩ riêng tới giải độc suốt đêm."),
    ("3:09:46-3:12:02", "Sáng hôm sau, nén lại cơn sốt cao do tác dụng phụ của thuốc, Uyển Vân vẫn kiên cường bước lên sân khấu trình bày xuất sắc ý tưởng bộ sưu tập mới trước khi ngất đi trong vòng tay của Hoắc Đình Uyên. Toàn bộ năm dòng sản phẩm tiếp tục bán sạch một vạn bộ mỗi mẫu, còn hai cô bạn thân của cô thì kéo thẳng tới trụ sở Bùi thị mắng cho Dật Phong một trận tơi bời."),
    ("3:12:05-3:14:00", "Sau thành công vang dội ấy, Hoắc Đình Uyên chính thức bổ nhiệm Lâm Uyển Vân làm nhà thiết kế trưởng của tập đoàn chỉ sau hai tháng làm việc, đồng thời công bố kế hoạch xây dựng thương hiệu trang sức cá nhân mang tên Chi Lan cho riêng cô và cử cô đại diện Hoắc thị tham dự cuộc thi thiết kế quốc tế."),
    ("3:14:05-3:17:00", "Đúng vào ngày thứ ba mươi kết thúc thời hạn chờ nhận giấy chứng nhận ly hôn, Bùi Dật Phong lại tìm tới gây sự dưới sảnh công ty rồi buông lời xúc phạm Hoắc Đình Uyên, nhưng bị Uyển Vân cùng bảo vệ tòa nhà thẳng tay đuổi đi."),
    ("3:17:05-3:21:30", "Thế nhưng khi Uyển Vân tới Cục Dân Chính để lấy giấy chứng nhận độc thân, cô mới bàng hoàng phát hiện Bùi Dật Phong đã hèn hạ lén rút đơn đăng ký ly hôn từ trước đó nhiều ngày. Cơn tức giận dồn nén khiến cô ngất xỉu ngay tại sảnh và được Hoắc Đình Uyên tức tốc đưa vào bệnh viện cấp cứu."),
    ("3:21:35-3:24:15", "Tỉnh dậy trong bệnh viện với sự động viên của hai cô bạn thân và Hoắc Đình Uyên, Uyển Vân quyết định giao toàn bộ hồ sơ cho luật sư Thẩm của đội ngũ pháp vụ Hoắc thị để chính thức khởi kiện ly hôn ra tòa."),
    ("3:24:30-3:33:10", "Để giúp Uyển Vân giải tỏa căng thẳng sau biến cố, Hoắc Đình Uyên đã tổ chức một chuyến nghỉ dưỡng bên bờ biển cho toàn bộ phòng thiết kế. Bùi Dật Phong cùng Bạch Hiểu Hiểu cố tình bám đuôi tới tận bãi biển gây sự, cô trợ lý còn định diễn trò ngã xuống nước để đổ tội cho Uyển Vân nhưng bị camera khu nghỉ dưỡng vạch trần tại chỗ."),
    ("3:33:15-3:38:25", "Đêm tiệc bên bờ biển ngập ánh đèn, dưới sự cổ vũ của các đồng nghiệp, Uyển Vân đã cùng Hoắc Đình Uyên khiêu vũ một bản nhạc lãng mạn ngay trước ánh mắt ghen tức bất lực của Dật Phong, buộc hắn và nhân tình phải lủi thủi kéo vali rời đi."),
    ("3:38:30-3:41:35", "Không chấp nhận thất bại, bà mẹ chồng Lương Tĩnh Nghi liền bỏ tiền thuê thủy quân và các tài khoản truyền thông bẩn tung tin đồn thất thiệt vu khống Uyển Vân cặp kè với tổng tài Hoắc thị để tiến thân. Ngay lập tức, Hoắc Đình Uyên chỉ đạo luật sư Thẩm truy vết toàn bộ địa chỉ mạng và báo cảnh sát lập án hình sự."),
    ("3:41:40-3:44:10", "Trong lúc Uyển Vân vừa hoàn thiện xong bản vẽ xuất sắc cho cuộc thi thiết kế quốc tế, cảnh sát đã tìm tới tận biệt thự nhà họ Bùi, đọc lệnh bắt giữ bà Lương Tĩnh Nghi ngay trước cửa vì tội vu khống phỉ báng nghiêm trọng."),
    ("3:44:15-3:53:40", "Tại đồn cảnh sát, Bùi Dật Phong cuống cuồng chạy tới xin bảo lãnh, thậm chí còn đem cả dự án đất vàng ở Thành Đông ra cầu xin Hoắc Đình Uyên giảng hòa. Thế nhưng cả Đình Uyên lẫn Uyển Vân đều dứt khoát từ chối hòa giải, mặc cho bà Lương Tĩnh Nghi trong phòng tạm giam gào thét điên cuồng."),
    ("3:54:28-3:57:10", "Giữa tâm bão dư luận, phu nhân nhà họ Hoắc đích thân tới thăm Uyển Vân, khẳng định gia đình bà không bao giờ có tư tưởng phong kiến phân biệt chuyện từng đổ vỡ hôn nhân. Và ngay trước mặt mẹ mình, Hoắc Đình Uyên đã chân thành thổ lộ tình cảm dành cho Uyển Vân, nhẹ nhàng hẹn rằng anh sẽ kiên nhẫn chờ tới ngày cô hoàn toàn tự do."),
    ("3:57:20-4:00:30", "Tối hôm đó, Hoắc Đình Uyên còn hào phóng tặng một chai rượu vang thượng hạng trị giá bằng nửa năm tiền lương cho Uyển Vân cùng hai cô bạn thân liên hoan, khiến hai người bạn hết lời khuyên cô hãy mở lòng đón nhận người đàn ông chân thành ấy sau khi hoàn tất thủ tục ly hôn."),
    ("4:00:35-4:04:40", "Để cứu mẹ ra khỏi đồn cảnh sát, Dật Phong phải chặn đường van xin Uyển Vân bất thành rồi đành tìm người nhận tội thay, nhưng ngay sau đó hắn lại nhận được giấy triệu tập mở phiên tòa ly hôn sớm từ luật sư Thẩm."),

    # ---------------- HỒI 9: GIẤY KHÁM THAI, VỤ THUÊ SÁT THỦ & ĐÒN KẾT LIỄU CHIA SÁU MƯƠI PHẦN TRĂM GIA SẢN ----------------
    ("4:04:45-4:06:50", "Hoảng loạn trước nguy cơ mất vợ tại tòa, Dật Phong lại chặn xe van xin Uyển Vân tha thứ và hứa sẽ tống cổ Bạch Hiểu Hiểu ra nước ngoài. Đúng lúc đó, điện thoại của Uyển Vân nhận được tờ phiếu siêu âm thai sáu tuần do chính Hiểu Hiểu gửi tới khiêu khích. Cô lập tức đưa thẳng cho Dật Phong xem và mỉa mai chúc mừng hắn sắp có quý tử."),
    ("4:06:55-4:09:30", "Điên tiết vì kế hoạch giữ vợ bị phá hỏng, Dật Phong lôi cổ Hiểu Hiểu tới bệnh viện ép phá thai ngay trong đêm. Thế nhưng bà Lương Tĩnh Nghi đã kịp thời lao tới ngăn cản, sống chết bảo vệ giọt máu nối dõi của nhà họ Bùi và đưa Hiểu Hiểu về nhà chính dưỡng thai."),
    ("4:09:32-4:12:30", "Vài ngày sau, khi Uyển Vân cùng Hoắc Đình Uyên tới trang viên của lão tiên sinh họ Trần để chọn đá quý cho cuộc thi thiết kế quốc tế, Bạch Hiểu Hiểu vì lo sợ sau khi sinh con sẽ bị Dật Phong vứt bỏ nên đã liều lĩnh chi mười triệu tệ thuê một toán sát thủ bắt cóc Uyển Vân ngay tại khu vực nhà vệ sinh biệt lập."),
    ("4:12:32-4:14:35", "Trong nhà kho hoang vắng, Uyển Vân bình tĩnh thương lượng trả gấp năm lần tiền chuộc để kéo dài thời gian. Khi tên cầm đầu gọi điện xác nhận, Bạch Hiểu Hiểu ở đầu dây bên kia đã điên cuồng hét giá sáu mươi triệu tệ để ra lệnh giết người diệt khẩu. Thấy đám bắt cóc nảy sinh ý đồ xấu, Uyển Vân dũng cảm tung cú đá hiểm hóc vào tên cầm đầu rồi vùng chạy ra ngoài."),
    ("4:14:38-4:15:40", "Ngay khoảnh khắc đám côn đồ đuổi kịp cô giữa rừng cây, Hoắc Đình Uyên đã dẫn người lao tới giải cứu kịp thời, đánh gục toàn bộ bọn bắt cóc và thu giữ chiếc điện thoại có nguyên vẹn đoạn ghi âm cuộc gọi thuê sát thủ giá sáu mươi triệu tệ của Bạch Hiểu Hiểu để giao nộp cho cảnh sát."),
    ("4:16:30-4:20:20", "Tại phiên tòa sơ thẩm vụ án ly hôn, vì Bùi Dật Phong vẫn cố chấp thề thốt còn yêu vợ nên thẩm phán tạm thời chưa tuyên hủy hôn ngay trong phiên đầu. Không chút nao núng, bước ra khỏi phòng xử án, Uyển Vân lập tức chỉ thị cho luật sư Thẩm tung ra quân bài kết liễu mang tên đơn khởi kiện hình sự tội cố ý giết người đối với Bạch Hiểu Hiểu."),
    ("4:20:25-4:24:00", "Khi luật sư Thẩm mang hồ sơ hình sự kèm đoạn ghi âm sáu mươi triệu tệ tới thẳng nhà chính họ Bùi và tuyên bố mức án từ mười năm tù tới chung thân, Bạch Hiểu Hiểu sợ hãi quỳ sụp xuống sàn, còn bà Lương Tĩnh Nghi cũng rụng rời tay chân vì sợ đứa cháu nội tương lai mang lý lịch có mẹ là kẻ sát nhân."),
    ("4:24:05-4:29:15", "Biết tin nhân tình thuê người giết vợ mình, Dật Phong nổi trận lôi đình. Trong lúc cãi vã, hắn buột miệng tiết lộ chuyện lần nào ở bên Hiểu Hiểu cũng bắt cô ả uống thuốc tránh thai, khiến cái thai trong bụng cô ả trở thành một dấu hỏi lớn, nhưng vì bị mẹ già lấy cái chết ra ép buộc, hắn đành phải cắn răng tìm cách giảng hòa với Uyển Vân."),
    ("4:29:20-4:31:45", "Trong lúc nhà họ Bùi rối như tơ vò, Uyển Vân và Hoắc Đình Uyên đã ký kết thành công hợp đồng cung ứng đá quý độc quyền với lão tiên sinh họ Trần cho vòng chung kết cuộc thi thiết kế trang sức quốc tế."),
    ("4:31:50-4:33:25", "Để giữ cho đứa cháu sắp chào đời không mang vết nhơ mẹ ngồi tù, bà Lương Tĩnh Nghi đã quay ngoắt thái độ, lấy mạng sống ra ép con trai phải lập tức ký giấy ly hôn với Lâm Uyển Vân để đổi lấy giấy bãi nại cho Bạch Hiểu Hiểu."),
    ("4:33:26-4:36:35", "Trên bàn đàm phán, nếu như trước đây Uyển Vân sẵn sàng ra đi tay trắng mà nhà họ Bùi không biết điều, thì nay cô cùng luật sư Thẩm thẳng tay yêu cầu chia sáu mươi phần trăm toàn bộ tiền mặt và bất động sản đứng tên Dật Phong, đồng thời tung thêm bằng chứng Hiểu Hiểu đăng ảnh sống chung để dọa khép thêm tội trùng hôn khiến mẹ con họ Bùi phải run rẩy ký tên."),
    ("4:36:40-4:37:40", "Toàn bộ hàng chục tỷ tài sản và biệt thự nhanh chóng được công chứng sang tên cho Lâm Uyển Vân, cùng lúc tác phẩm của cô tại cuộc thi thiết kế trang sức quốc tế cũng được đặc cách tiến thẳng vào vòng chung kết."),
    ("4:37:45-4:39:30", "Đêm trước ngày ra Cục Dân Chính nhận giấy ly hôn, Bùi Dật Phong vì quá suy sụp đã phóng xe quá tốc độ dẫn tới tai nạn gãy chân phải nằm viện. Khi Uyển Vân cùng Hoắc Đình Uyên tới phòng bệnh, bà Lương Tĩnh Nghi còn định bắt cô ở lại hầu hạ con trai, nhưng Uyển Vân chỉ cười lạnh buông một câu rằng ly hôn thì lâu chứ chờ thành góa phụ có khi lại nhanh hơn, khiến Dật Phong đành ngậm ngùi ký giấy ủy quyền toàn bộ cho luật sư."),
    ("4:39:15-4:39:55", "Bước ra khỏi Cục Dân Chính với cuốn sổ ly hôn đỏ thắm trên tay, khi luật sư của Dật Phong còn nhắn lại rằng hắn sẽ chờ ngày theo đuổi lại cô, Uyển Vân thẳng thừng bảo hắn hãy dắt theo cô nhân tình độc ác, bà mẹ điên cuồng và đứa con chưa rõ lai lịch kia cút thật xa khỏi cuộc đời cô."),
    ("4:39:56-4:40:54", "Ngay dưới bậc thềm ngập nắng, Hoắc Đình Uyên đã đứng đợi sẵn với một hộp trang sức trên tay. Bên trong chính là chiếc dây chuyền đầu tiên cô thiết kế cho Hoắc thị mang mã số độc bản không không một, cùng lời tỏ tình chân thành rằng anh đã đợi ngày cô tự do từ rất lâu rồi, khép lại những năm tháng u tối để mở ra một chương đời rạng rỡ và hạnh phúc viên mãn."),
]
